    /**
     * Method to retrieve the Measure via MeasureFetchOneSummary
     * @param 	summary MeasureFetchOneSummary 
     * @return 	MeasureFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Measure getMeasure( MeasureFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "MeasureFetchOneSummary arg cannot be null" );
    	
    	Measure entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Measure
        	// --------------------------------------
        	CompletableFuture<Measure> futureEntity = queryGateway.query(new FindMeasureQuery( new LoadMeasureFilter( summary.getMeasureId() ) ), ResponseTypes.instanceOf(Measure.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Measure with id " + summary.getMeasureId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


